MAX_ENTRIES = 20_000
MAX_FILES = 10_000
MAX_FILE_BYTES = 8 * 1024 * 1024
MAX_TOTAL_BYTES = 64 * 1024 * 1024
MAX_PATH_BYTES = 1024
MAX_BINDING_BYTES = 256 * 1024
MAX_REPORT_BYTES = 64 * 1024
